from django.test import SimpleTestCase


class TestSubclasses(SimpleTestCase):
    def test_subclasses_yields_class(self):
        from django.db.models.query_utils import subclasses

        class Base:
            pass

        results = list(subclasses(Base))
        self.assertIn(Base, results)

    def test_subclasses_yields_subclasses(self):
        from django.db.models.query_utils import subclasses

        class Base:
            pass

        class Child(Base):
            pass

        results = list(subclasses(Base))
        self.assertIn(Base, results)
        self.assertIn(Child, results)


class TestQ(SimpleTestCase):
    def test_q_init_with_kwargs(self):
        from django.db.models import Q

        q = Q(name='test')
        self.assertEqual(len(q.children), 1)

    def test_q_init_with_args(self):
        from django.db.models import Q

        q1 = Q(name='test')
        q2 = Q(age__gt=5)
        q = Q(q1, q2)
        self.assertEqual(len(q.children), 2)

    def test_q_or_operator(self):
        from django.db.models import Q

        q1 = Q(name='test')
        q2 = Q(age__gt=5)
        q = q1 | q2
        self.assertEqual(q.connector, 'OR')

    def test_q_and_operator(self):
        from django.db.models import Q

        q1 = Q(name='test')
        q2 = Q(age__gt=5)
        q = q1 & q2
        self.assertEqual(q.connector, 'AND')

    def test_q_invert_operator(self):
        from django.db.models import Q

        q = ~Q(name='test')
        self.assertTrue(q.negated)

    def test_q_or_with_empty_q(self):
        from django.db.models import Q

        q1 = Q(name='test')
        q2 = Q()
        result = q1 | q2
        self.assertEqual(result.children, q1.children)

    def test_q_and_with_empty_q(self):
        from django.db.models import Q

        q1 = Q()
        q2 = Q(name='test')
        result = q1 & q2
        self.assertEqual(result.children, q2.children)

    def test_q_or_raises_typeerror(self):
        from django.db.models import Q

        q = Q(name='test')
        with self.assertRaises(TypeError):
            q | 'invalid'

    def test_q_and_raises_typeerror(self):
        from django.db.models import Q

        q = Q(name='test')
        with self.assertRaises(TypeError):
            q & 'invalid'

    def test_q_deconstruct_simple(self):
        from django.db.models import Q

        q = Q(name='test')
        path, args, kwargs = q.deconstruct()
        self.assertIn('name', kwargs)

    def test_q_deconstruct_multiple_children(self):
        from django.db.models import Q

        q1 = Q(name='test')
        q2 = Q(age__gt=5)
        q = q1 & q2
        path, args, kwargs = q.deconstruct()
        self.assertEqual(len(args), 2)

    def test_q_deconstruct_non_default_connector(self):
        from django.db.models import Q

        q1 = Q(name='test')
        q2 = Q(age__gt=5)
        q = Q(q1, q2, _connector='OR')
        path, args, kwargs = q.deconstruct()
        self.assertIn('_connector', kwargs)

    def test_q_deconstruct_negated(self):
        from django.db.models import Q

        q = Q(name='test', _negated=True)
        path, args, kwargs = q.deconstruct()
        self.assertIn('_negated', kwargs)

    def test_q_resolve_expression(self):
        from django.db.models import Q

        q = Q(name='test')
        # Just verify the method exists and has correct signature
        self.assertTrue(hasattr(q, 'resolve_expression'))
        import inspect
        sig = inspect.signature(q.resolve_expression)
        params = list(sig.parameters.keys())
        self.assertIn('query', params)


