class TestRegisterLookupMixin(SimpleTestCase):
    def test_get_lookup_found(self):
        from django.db.models.query_utils import RegisterLookupMixin

        class TestClass(RegisterLookupMixin):
            class_lookups = {'test_lookup': 'lookup_value'}

        lookup = TestClass._get_lookup('test_lookup')
        self.assertEqual(lookup, 'lookup_value')

    def test_get_lookup_not_found(self):
        from django.db.models.query_utils import RegisterLookupMixin

        class TestClass(RegisterLookupMixin):
            class_lookups = {}

        lookup = TestClass._get_lookup('nonexistent')
        self.assertIsNone(lookup)

    def test_get_lookups_cached(self):
        from django.db.models.query_utils import RegisterLookupMixin

        class TestClass(RegisterLookupMixin):
            class_lookups = {'test': 'value'}

        lookups1 = TestClass.get_lookups()
        lookups2 = TestClass.get_lookups()
        self.assertIs(lookups1, lookups2)

    def test_merge_dicts_order(self):
        from django.db.models.query_utils import RegisterLookupMixin

        d1 = {'a': 1, 'b': 2}
        d2 = {'b': 3, 'c': 4}
        result = RegisterLookupMixin.merge_dicts([d1, d2])
        self.assertEqual(result['b'], 2)
        self.assertEqual(result['a'], 1)
        self.assertEqual(result['c'], 4)

    def test_clear_cached_lookups(self):
        from django.db.models.query_utils import RegisterLookupMixin

        class TestClass(RegisterLookupMixin):
            class_lookups = {'test': 'value'}

        TestClass._clear_cached_lookups()
        # Should not raise an error

    def test_register_lookup(self):
        from django.db.models.query_utils import RegisterLookupMixin

        class TestClass(RegisterLookupMixin):
            pass

        class MockLookup:
            lookup_name = 'custom_lookup'

        result = TestClass.register_lookup(MockLookup)
        self.assertIn('custom_lookup', TestClass.class_lookups)
        self.assertIs(result, MockLookup)

    def test_register_lookup_custom_name(self):
        from django.db.models.query_utils import RegisterLookupMixin

        class TestClass(RegisterLookupMixin):
            pass

        class MockLookup:
            lookup_name = 'original'

        result = TestClass.register_lookup(MockLookup, 'custom_name')
        self.assertIn('custom_name', TestClass.class_lookups)

    def test_unregister_lookup(self):
        from django.db.models.query_utils import RegisterLookupMixin

        class TestClass(RegisterLookupMixin):
            class_lookups = {'test': 'value'}

        class MockLookup:
            lookup_name = 'test'

        TestClass._unregister_lookup(MockLookup)
        self.assertNotIn('test', TestClass.class_lookups)


