        annotations = {'other': 'value'}
        lookup_parts = ['field', 'subfield']
        result, remaining = refs_expression(lookup_parts, annotations)
        self.assertFalse(result)
        self.assertEqual(remaining, ())

    def test_refs_expression_match(self):
        from django.db.models.query_utils import refs_expression

        annotations = {'field__subfield': 'value'}
        lookup_parts = ['field', 'subfield']
        result, remaining = refs_expression(lookup_parts, annotations)
        self.assertEqual(result, 'value')
        self.assertEqual(list(remaining), [])

