class TestFilteredRelation(SimpleTestCase):
    def test_init_valid(self):
        from django.db.models import Q
        from django.db.models.query_utils import FilteredRelation

        fr = FilteredRelation('relation_name', condition=Q())
        self.assertEqual(fr.relation_name, 'relation_name')
        self.assertIsNotNone(fr.condition)

    def test_init_empty_relation_name(self):
        from django.db.models import Q
        from django.db.models.query_utils import FilteredRelation

        with self.assertRaises(ValueError):
            FilteredRelation('', condition=Q())

    def test_init_invalid_condition(self):
        from django.db.models.query_utils import FilteredRelation

        with self.assertRaises(ValueError):
            FilteredRelation('relation_name', condition='not_a_q')

    def test_eq_same(self):
        from django.db.models import Q
        from django.db.models.query_utils import FilteredRelation

        fr1 = FilteredRelation('rel', condition=Q())
        fr2 = FilteredRelation('rel', condition=Q())
        self.assertEqual(fr1, fr2)

    def test_eq_different_relation_name(self):
        from django.db.models import Q
        from django.db.models.query_utils import FilteredRelation

        fr1 = FilteredRelation('rel1', condition=Q())
        fr2 = FilteredRelation('rel2', condition=Q())
        self.assertNotEqual(fr1, fr2)

    def test_eq_different_alias(self):
        from django.db.models import Q
        from django.db.models.query_utils import FilteredRelation

        fr1 = FilteredRelation('rel', condition=Q())
        fr1.alias = 'alias1'
        fr2 = FilteredRelation('rel', condition=Q())
        fr2.alias = 'alias2'
        self.assertNotEqual(fr1, fr2)

    def test_eq_different_condition(self):
        from django.db.models import Q
        from django.db.models.query_utils import FilteredRelation

        fr1 = FilteredRelation('rel', condition=Q(name='test'))
        fr2 = FilteredRelation('rel', condition=Q(name='other'))
        self.assertNotEqual(fr1, fr2)

    def test_eq_with_non_filtered_relation(self):
        from django.db.models.query_utils import FilteredRelation

        fr = FilteredRelation('rel')
        self.assertNotEqual(fr, 'not a FilteredRelation')
        self.assertNotEqual(fr, 123)
        self.assertNotEqual(fr, None)

    def test_clone(self):
        from django.db.models import Q
        from django.db.models.query_utils import FilteredRelation

        fr1 = FilteredRelation('rel', condition=Q())
        fr1.alias = 'alias1'
        fr1.path = ['path1']

        fr2 = fr1.clone()
        self.assertEqual(fr2.relation_name, fr1.relation_name)
        self.assertEqual(fr2.alias, fr1.alias)
        self.assertEqual(fr2.path, fr1.path[:])

    def test_resolve_expression_not_implemented(self):
        from django.db.models.query_utils import FilteredRelation

        fr = FilteredRelation('rel')
        with self.assertRaises(NotImplementedError):
            fr.resolve_expression()

    def test_as_sql(self):
        from django.db.models.query_utils import FilteredRelation

        fr = FilteredRelation('rel')
        # Just verify the method exists and doesn't crash in basic inspection
        self.assertTrue(hasattr(fr, 'as_sql'))

