class TestManagementForm(SimpleTestCase):
    """Tests for ManagementForm class."""

    def test_management_form_clean(self):
        from django.forms.formsets import ManagementForm
        form = ManagementForm(data={})
        form.full_clean()  # Need to call full_clean first
        cleaned_data = form.clean()
        self.assertEqual(cleaned_data[TOTAL_FORM_COUNT], 0)
        self.assertEqual(cleaned_data[INITIAL_FORM_COUNT], 0)

    def test_management_form_with_data(self):
        from django.forms.formsets import ManagementForm
        data = {
            'TOTAL_FORMS': '3',
            'INITIAL_FORMS': '2',
            'MIN_NUM_FORMS': '0',
            'MAX_NUM_FORMS': '1000',
        }
        form = ManagementForm(data=data)
        self.assertTrue(form.is_valid())
        self.assertEqual(form.cleaned_data[TOTAL_FORM_COUNT], 3)
        self.assertEqual(form.cleaned_data[INITIAL_FORM_COUNT], 2)


