class UserCreationFormTests(TestCase):
    def setUp(self):
        from django.contrib.auth.forms import UserCreationForm
        self.form_class = UserCreationForm

    def test_valid_creation(self):
        form = self.form_class({
            'username': 'testuser',
            'password1': 'testpass123',
            'password2': 'testpass123',
        })
        self.assertTrue(form.is_valid())
        user = form.save()
        self.assertEqual(user.username, 'testuser')
        self.assertTrue(user.check_password('testpass123'))

    def test_password_mismatch(self):
        form = self.form_class({
            'username': 'testuser',
            'password1': 'password1',
            'password2': 'password2',
        })
        self.assertFalse(form.is_valid())
        self.assertIn('password2', form.errors)

    def test_clean_password2_mismatch(self):
        from django.contrib.auth.forms import UserCreationForm
        form = UserCreationForm({
            'username': 'testuser',
            'password1': 'pass1',
            'password2': 'pass2',
        })
        # clean_password2 raises ValidationError when passwords don't match
        with self.assertRaises(ValidationError):
            form.clean_password2()

    def test_save_without_commit(self):
        from django.contrib.auth.forms import UserCreationForm
        form = UserCreationForm({
            'username': 'testuser',
            'password1': 'testpass123',
            'password2': 'testpass123',
        })
        user = form.save(commit=False)
        self.assertEqual(user.username, 'testuser')
        self.assertTrue(user.check_password('testpass123'))

    def test_password_validation_in_post_clean(self):
        from django.contrib.auth.forms import UserCreationForm
        # Use a very short password that will fail validation
        form = UserCreationForm({
            'username': 'testuser',
            'password1': 'a',
            'password2': 'a',
        })
        # This should fail password validation
        is_valid = form.is_valid()
        self.assertFalse(is_valid)
        self.assertIn('password2', form.errors)


