class MultiDecorateTests(SimpleTestCase):
    """Tests for _multi_decorate function."""

    def setUp(self):
        self.rf = RequestFactory()

    def test_multi_decorate_single_decorator(self):
        """Test _multi_decorate with a single decorator."""
        from django.utils.decorators import _multi_decorate

        decorator_called = [False]  # Use list for closure mutation

        def my_decorator(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                decorator_called[0] = True
                return func(*args, **kwargs)
            return wrapper

        class TestView:
            def my_method(self, request):
                return HttpResponse("OK")

        decorated = _multi_decorate(my_decorator, TestView.my_method)
        view = TestView()
        response = decorated(view, self.rf.get('/'))
        self.assertTrue(decorator_called[0])

    def test_multi_decorate_multiple_decorators(self):
        """Test _multi_decorate with multiple decorators."""
        from django.utils.decorators import _multi_decorate

        call_order = []

        def decorator1(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                call_order.append(1)
                return func(*args, **kwargs)
            return wrapper

        def decorator2(func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                call_order.append(2)
                return func(*args, **kwargs)
            return wrapper

        class TestView:
            def my_method(self, request):
                return HttpResponse("OK")

        decorated = _multi_decorate([decorator1, decorator2], TestView.my_method)
        view = TestView()
        response = decorated(view, self.rf.get('/'))
        # Decorators are applied in reverse order, so decorator1 runs first (outermost)
        self.assertEqual(call_order, [1, 2])


