class DecoratorFromMiddlewareTests(SimpleTestCase):
    """Tests for decorator_from_middleware function."""

    def setUp(self):
        self.rf = RequestFactory()

    def test_decorator_from_middleware_basic(self):
        """Test basic decorator_from_middleware usage."""
        class BasicMiddleware:
            def __init__(self, get_response):
                self.get_response = get_response

            def process_request(self, request):
                request.middleware_reached = True

        dec = decorator_from_middleware(BasicMiddleware)

        @dec
        def my_view(request):
            return HttpResponse("OK")

        request = self.rf.get('/')
        response = my_view(request)
        self.assertTrue(getattr(request, 'middleware_reached', False))

    def test_decorator_from_middleware_process_view_early_return(self):
        """Test middleware with process_view returning early."""
        class EarlyReturnMiddleware:
            def __init__(self, get_response):
                self.get_response = get_response

            def process_view(self, request, view_func, args, kwargs):
                return HttpResponse("Process view early return")

        dec = decorator_from_middleware(EarlyReturnMiddleware)

        @dec
        def my_view(request):
            request.view_called = True
            return HttpResponse("OK")

        request = self.rf.get('/')
        response = my_view(request)
        self.assertFalse(getattr(request, 'view_called', False))
        self.assertEqual(response.content, b"Process view early return")

    def test_decorator_from_middleware_process_template_with_callback(self):
        """Test middleware with process_response callback on TemplateResponse."""
        class CallbackMiddleware:
            def __init__(self, get_response):
                self.get_response = get_response

            def process_response(self, request, response):
                request.process_response_called = True
                return response

        dec = decorator_from_middleware(CallbackMiddleware)

        @dec
        def template_view(request):
            template = engines['django'].from_string("Hello")
            return TemplateResponse(request, template)

        request = self.rf.get('/')
        response = template_view(request)
        # process_response is deferred until render() is called
        self.assertFalse(getattr(request, 'process_response_called', False))
        response.render()
        self.assertTrue(getattr(request, 'process_response_called', False))

    def test_decorator_from_middleware_process_exception(self):
        """Test middleware with process_exception."""
        class ExceptionMiddleware:
            def __init__(self, get_response):
                self.get_response = get_response

            def process_exception(self, request, exception):
                request.exception_handled = True
                return HttpResponse("Handled")

        dec = decorator_from_middleware(ExceptionMiddleware)

        @dec
        def failing_view(request):
            raise ValueError("Test error")

        request = self.rf.get('/')
        response = failing_view(request)
        self.assertTrue(getattr(request, 'exception_handled', False))
        self.assertEqual(response.status_code, 200)

    def test_decorator_from_middleware_process_template_response(self):
        """Test middleware with process_template_response."""
        class TemplateMiddleware:
            def __init__(self, get_response):
                self.get_response = get_response

            def process_template_response(self, request, response):
                request.template_processed = True
                return response

        dec = decorator_from_middleware(TemplateMiddleware)

        @dec
        def template_view(request):
            template = engines['django'].from_string("Hello")
            return TemplateResponse(request, template)

        request = self.rf.get('/')
        response = template_view(request)
        # process_template_response is called immediately when response is returned
        self.assertTrue(getattr(request, 'template_processed', False))
        # response must not be rendered yet
        self.assertFalse(response._is_rendered)

    def test_decorator_from_middleware_process_response(self):
        """Test middleware with process_response."""
        class ResponseMiddleware:
            def __init__(self, get_response):
                self.get_response = get_response

            def process_response(self, request, response):
                request.response_modified = True
                return response

        dec = decorator_from_middleware(ResponseMiddleware)

        @dec
        def my_view(request):
            return HttpResponse("OK")

        request = self.rf.get('/')
        response = my_view(request)
        self.assertTrue(getattr(request, 'response_modified', False))

    def test_decorator_from_middleware_early_return(self):
        """Test middleware returning early from process_request."""
        class EarlyReturnMiddleware:
            def __init__(self, get_response):
                self.get_response = get_response

            def process_request(self, request):
                return HttpResponse("Early return")

        dec = decorator_from_middleware(EarlyReturnMiddleware)

        @dec
        def my_view(request):
            request.view_called = True
            return HttpResponse("OK")

        request = self.rf.get('/')
        response = my_view(request)
        self.assertFalse(getattr(request, 'view_called', False))
        self.assertEqual(response.content, b"Early return")


