class ModelSignalsTests(TestCase):
    """Tests for model signals."""

    def test_pre_init_signal(self):
        signal_called = []

        def pre_init_handler(sender, **kwargs):
            signal_called.append(True)

        from django.db.models.signals import pre_init

        class TestModel(Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'test'

        pre_init.connect(pre_init_handler)
        try:
            obj = TestModel(name='test')
        finally:
            pre_init.disconnect(pre_init_handler)

        self.assertTrue(len(signal_called) > 0)

    def test_post_init_signal(self):
        signal_called = []

        def post_init_handler(sender, instance, **kwargs):
            signal_called.append(True)

        from django.db.models.signals import post_init

        class TestModel(Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'test'

        post_init.connect(post_init_handler)
        try:
