class TestDeferred(SimpleTestCase):
    """Tests for Deferred class."""

    def test_deferred_repr(self):
        from django.db.models.base import Deferred
        d = Deferred()
        self.assertEqual(repr(d), '<Deferred field>')

    def test_deferred_str(self):
        from django.db.models.base import Deferred
        d = Deferred()
        self.assertEqual(str(d), '<Deferred field>')


class TestSubclassException(SimpleTestCase):
    """Tests for subclass_exception function."""

    def test_subclass_exception_creation(self):
        from django.db.models.base import subclass_exception

        class DummyClass:
            __qualname__ = 'DummyClass'

        exc_class = subclass_exception(
            'MyException',
            (ValueError,),
            'test_module',
            attached_to=DummyClass
        )

        self.assertTrue(issubclass(exc_class, ValueError))
        self.assertEqual(exc_class.__module__, 'test_module')
        self.assertEqual(exc_class.__qualname__, 'DummyClass.MyException')


class TestHasContributeToClass(SimpleTestCase):
    """Tests for _has_contribute_to_class function."""

    def test_has_contribute_to_class_with_bound_method(self):
        from django.db.models.base import _has_contribute_to_class

        class MyClass:
            def contribute_to_class(self, cls, name):
                pass

        obj = MyClass()
        self.assertTrue(_has_contribute_to_class(obj))

    def test_has_contribute_to_class_without_method(self):
        from django.db.models.base import _has_contribute_to_class

        class MyClass:
            pass

        obj = MyClass()
        self.assertFalse(_has_contribute_to_class(obj))

    def test_has_contribute_to_class_with_class(self):
        from django.db.models.base import _has_contribute_to_class

        class MyClass:
            pass

        # Classes are not considered as having contribute_to_class
        self.assertFalse(_has_contribute_to_class(MyClass))


