class TestConstructInstance(SimpleTestCase):
    """Tests for construct_instance function."""

    def test_construct_instance_basic(self):
        form_data = {'name': 'test', 'value': 100}

        class MockForm:
            cleaned_data = form_data
            data = form_data
            files = {}

            def __getitem__(self, name):
                field = models.CharField(max_length=255)
                return type('obj', (object,), {
                    'field': field,
                    'field_empty_values': []
                })()

        instance = Defaults()
        form = MockForm()
        result = construct_instance(form, instance, fields=['name', 'value'])
        self.assertEqual(result.name, 'test')
        self.assertEqual(result.value, 100)

    def test_construct_instance_with_exclude(self):
        form_data = {'name': 'test', 'value': 100}

        class MockForm:
            cleaned_data = form_data
            data = form_data
            files = {}

            def __getitem__(self, name):
                field = models.CharField(max_length=255)
                return type('obj', (object,), {
                    'field': field,
                    'field_empty_values': []
                })()

        instance = Defaults()
        form = MockForm()
        result = construct_instance(form, instance, exclude=['name'])
        self.assertNotEqual(result.name, 'test')
        self.assertEqual(result.value, 100)


