"""Tests for django.utils.html utilities."""

from django.test import SimpleTestCase
from django.utils.safestring import SafeString, mark_safe


class EscapeTests(SimpleTestCase):
    """Tests for escape() function."""

    def test_escape_basic(self):
        from django.utils.html import escape
        self.assertEqual(escape("<script>"), "&lt;script&gt;")
        self.assertEqual(escape("Hello & World"), "Hello &amp; World")
        self.assertEqual(escape('"quotes"'), "&quot;quotes&quot;")

    def test_escape_returns_safestring(self):
        from django.utils.html import escape
        result = escape("<test>")
        self.assertIsInstance(result, SafeString)

    def test_escape_double_escaping(self):
        from django.utils.html import escape
        # Always escapes input, even if already escaped
        self.assertEqual(escape("&lt;test&gt;"), "&amp;lt;test&amp;gt;")

    def test_escape_empty_string(self):
