class HtmlSafeDecoratorTests(SimpleTestCase):
    """Tests for @html_safe decorator."""

    def test_html_safe_decorator(self):
        from django.utils.html import html_safe

        @html_safe
        class MyStr:
            def __str__(self):
                return "my string"

        obj = MyStr()
        self.assertEqual(str(obj), "my string")
        self.assertTrue(hasattr(obj, "__html__"))
        self.assertEqual(obj.__html__(), "my string")

    def test_html_safe_raises_if_has_html(self):
        from django.utils.html import html_safe

        class HasHtml:
            def __str__(self):
                return "has html"
            def __html__(self):
                return "html"

        with self.assertRaises(ValueError):
            @html_safe
            class TestClass(HasHtml):
                pass

    def test_html_safe_raises_if_no_str(self):
        from django.utils.html import html_safe

        class NoStr:
            def __html__(self):
                return "html"

        with self.assertRaises(ValueError):
            @html_safe
            class TestClass(NoStr):
                pass

    def test_html_safe_raises_when_has_html_in_dict(self):
        from django.utils.html import html_safe

        # Create a class that has __html__ in its own __dict__
        class HasHtmlInDict:
            def __str__(self):
                return "has html"
            __html__ = lambda self: "html"

        with self.assertRaises(ValueError) as cm:
            @html_safe
            class TestClass(HasHtmlInDict):
                pass
        self.assertIn("__html__", str(cm.exception))


