        # The PostgreSQL client handles missing keys gracefully, no KeyError raised
        result = self.settings_to_cmd_args_env({})
        # Should return args with default postgres db and None env
        self.assertEqual(result[0], ["psql", "postgres"])
        self.assertIsNone(result[1])

