        expected_args = [
            "psql",
            "-U", "someuser",
            "-h", "somehost",
            "-p", "444",
            "somedbname",
        ]
        expected_env = {"PGPASSWORD": "somepassword"}
        self.assertEqual(
            self.settings_to_cmd_args_env(
                {
                    "NAME": "somedbname",
                    "USER": "someuser",
                    "PASSWORD": "somepassword",
