from django.template.defaultfilters import join
from django.test import SimpleTestCase
from django.utils.safestring import mark_safe

from ..utils import setup


class JoinTests(SimpleTestCase):
    @setup({"join01": "{{ a|join:', ' }}"})
    def test_join01(self):
        output = self.engine.render_to_string(
            "join01", {"a": ["a&b", "x"]}
        )
        self.assertEqual(output, "a&amp;b, x")

    @setup({"join02": "{% autoescape off %}{{ a|join:', ' }}{% endautoescape %}"})
    def test_join02(self):
        output = self.engine.render_to_string(
            "join02", {"a": ["a&b", "x"]}
        )
        self.assertEqual(output, "a&b, x")

    @setup({"join03": "{{ a|join:' - ' }}"})
    def test_join03(self):
        output = self.engine.render_to_string(
            "join03", {"a": ["hello", "world"]}
        )
        self.assertEqual(output, "hello - world")

    @setup({"join04": "{{ a|join:'' }}"})
    def test_join04(self):
        output = self.engine.render_to_string(
            "join04", {"a": ["a", "b", "c"]}
        )
        self.assertEqual(output, "abc")

    @setup({"join05": "{{ a|join:'|' }}"})
    def test_join05(self):
        output = self.engine.render_to_string(
            "join05", {"a": [mark_safe("a&b"), "x"]}
        )
        self.assertEqual(output, "a&b|x")

    @setup({"join06": "{% autoescape off %}{{ a|join:'|' }}{% endautoescape %}"})
    def test_join06(self):
        output = self.engine.render_to_string(
            "join06", {"a": [mark_safe("a&b"), "x"]}
        )
        self.assertEqual(output, "a&b|x")


class FunctionTests(SimpleTestCase):
    def test_basic_join(self):
        """Test basic joining of strings."""
        result = join(["a", "b", "c"], ", ")
        self.assertEqual(result, "a, b, c")

    def test_empty_list(self):
        """Test joining an empty list."""
        result = join([], ", ")
        self.assertEqual(result, "")

    def test_single_item(self):
        """Test joining a single item."""
        result = join(["only"], ", ")
        self.assertEqual(result, "only")

    def test_with_mark_safe_input(self):
        """Test joining with SafeString input."""
        safe_value = mark_safe("safe content")
        result = join([safe_value, "normal"], " | ")
        self.assertTrue(hasattr(result, '__html__'))

    def test_with_mark_safe_separator(self):
        """Test joining with SafeString separator."""
        safe_sep = mark_safe(" | ")
        result = join(["a", "b"], safe_sep)
        self.assertTrue(hasattr(result, '__html__'))

    def test_with_numbers_in_list(self):
        """Test joining a list containing numbers."""
        result = join([1, 2, 3], "-")
        self.assertEqual(result, "1-2-3")

    def test_with_mixed_types(self):
        """Test joining a list with mixed types."""
        result = join(["text", 123, True], " + ")
        self.assertEqual(result, "text + 123 + True")

    def test_typeerror_fails_silently(self):
        """Test that TypeError is handled gracefully."""
        # When arg isn't iterable, it gets converted to string
        result = join(["a", "b"], None)
        self.assertEqual(result, "aNoneb")

    def test_empty_separator(self):
        """Test joining with empty separator."""
        result = join(["x", "y", "z"], "")
        self.assertEqual(result, "xyz")

    def test_multiline_separator(self):
        """Test joining with multiline separator."""
        result = join(["line1", "line2"], "\n")
        self.assertEqual(result, "line1\nline2")

    def test_unicode_separator(self):
        """Test joining with unicode separator."""
        result = join(["a", "b", "c"], " → ")
        self.assertEqual(result, "a → b → c")

    def test_special_characters_in_items(self):
        """Test joining items with special characters."""
        result = join(["<script>", "</script>"], " & ")
        self.assertIn("&lt;script&gt;", str(result))

    def test_autoescape_false_preserves_html(self):
        """Test that autoescape=False preserves HTML."""
        result = join(["<b>bold</b>", "<i>italic</i>"], " | ", autoescape=False)
        self.assertEqual(result, "<b>bold</b> | <i>italic</i>")

    def test_autoescape_true_escapes_html(self):
        """Test that autoescape=True escapes HTML."""
        result = join(["<b>bold</b>", "<i>italic</i>"], " | ", autoescape=True)
        self.assertIn("&lt;b&gt;", str(result))

    def test_long_list(self):
        """Test joining a long list."""
        long_list = list(range(100))
        result = join(long_list, ", ")
        expected = ", ".join(str(i) for i in range(100))
        self.assertEqual(result, expected)

    def test_none_values_in_list(self):
        """Test joining a list with None values."""
        result = join([None, "value", None], " | ")
        self.assertEqual(result, "None | value | None")

    def test_whitespace_handling(self):
        """Test joining with whitespace in items."""
        result = join([" hello ", " world "], "-")
        self.assertEqual(result, " hello -  world ")

    def test_boolean_values(self):
        """Test joining boolean values with autoescape off."""
        # Boolean values cause TypeError, which is caught and returns original value
        result = join([True, False, True], " && ", autoescape=False)
        self.assertEqual(result, [True, False, True])

    def test_float_values(self):
        """Test joining float values."""
        result = join([1.5, 2.7, 3.9], " + ")
        self.assertEqual(result, "1.5 + 2.7 + 3.9")

    def test_return_type_is_mark_safe(self):
        """Test that return value is always marked safe."""
        result = join(["a", "b"], ", ")
        self.assertTrue(hasattr(result, '__html__'))

    def test_non_string_items_with_autoescape_true(self):
        """Test joining non-string items with autoescape=True."""
        # Non-string items cause TypeError, which is caught and returns original value
        result = join([True, False, True], " && ", autoescape=True)
        self.assertEqual(result, [True, False, True])

    def test_integer_items_with_autoescape_true(self):
        """Test joining integer items with autoescape=True."""
        # Integer items cause TypeError, which is caught and returns original value
        result = join([1, 2, 3], "-")
        self.assertEqual(result, [1, 2, 3])

"""Tests for _set_output module."""
import numpy as np
import pytest


class TestWrapInPandasContainer:
    """Tests for _wrap_in_pandas_container function."""

    def test_sparse_data_raises_value_error(self):
        """Test that sparse data raises ValueError."""
        from sklearn.utils._set_output import _wrap_in_pandas_container
        from scipy.sparse import csr_matrix

        sparse_data = csr_matrix(np.array([[1, 2], [3, 4]]))
        with pytest.raises(ValueError, match="Pandas output does not support sparse data"):
            _wrap_in_pandas_container(sparse_data, columns=["a", "b"])

    def test_callable_columns_success(self):
        """Test callable columns that returns successfully."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        def get_columns():
            return ["col1", "col2"]

        data = np.array([[1, 2], [3, 4]])
        result = _wrap_in_pandas_container(data, columns=get_columns)
        assert list(result.columns) == ["col1", "col2"]

    def test_callable_columns_raises_exception(self):
        """Test callable columns that raises an exception."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        def bad_columns():
            raise RuntimeError("bad")

        data = np.array([[1, 2], [3, 4]])
        result = _wrap_in_pandas_container(data, columns=bad_columns)
        # Should fall back to range(n_features)
        assert list(result.columns) == [0, 1]

    def test_columns_none_with_dataframe_input(self):
        """Test columns=None with DataFrame input doesn't change columns."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        pd = pytest.importorskip("pandas")
        df = pd.DataFrame({"a": [1, 2], "b": [3, 4]})
        result = _wrap_in_pandas_container(df, columns=None)
        assert list(result.columns) == ["a", "b"]

    def test_columns_none_with_ndarray_input(self):
        """Test columns=None with ndarray input creates range columns."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        data = np.array([[1, 2], [3, 4]])
        result = _wrap_in_pandas_container(data, columns=None)
        assert list(result.columns) == [0, 1]

    def test_columns_list_with_dataframe_input(self):
        """Test columns list with DataFrame input changes columns."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        pd = pytest.importorskip("pandas")
        df = pd.DataFrame({"a": [1, 2], "b": [3, 4]})
        result = _wrap_in_pandas_container(df, columns=["x", "y"])
        assert list(result.columns) == ["x", "y"]

    def test_index_parameter_ignored_for_dataframe(self):
        """Test index parameter is ignored when input is DataFrame."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        pd = pytest.importorskip("pandas")
        df = pd.DataFrame({"a": [1, 2], "b": [3, 4]}, index=[0, 1])
        result = _wrap_in_pandas_container(df, columns=["x", "y"], index=[10, 20])
        assert list(result.index) == [0, 1]

    def test_index_parameter_applied_to_ndarray(self):
        """Test index parameter is applied when input is ndarray."""
        from sklearn.utils._set_output import _wrap_in_pandas_container

        data = np.array([[1, 2], [3, 4]])
        result = _wrap_in_pandas_container(data, columns=["x", "y"], index=[10, 20])
        assert list(result.index) == [10, 20]


