class TestGetWeights:
    """Tests for _get_weights function."""

    def test_get_weights_uniform(self):
        from sklearn.neighbors.base import _get_weights
        dist = np.array([[1.0, 2.0], [3.0, 4.0]])
        result = _get_weights(dist, 'uniform')
        assert result is None

    def test_get_weights_none(self):
        from sklearn.neighbors.base import _get_weights
        dist = np.array([[1.0, 2.0], [3.0, 4.0]])
        result = _get_weights(dist, None)
        assert result is None

    def test_get_weights_distance(self):
        from sklearn.neighbors.base import _get_weights
        dist = np.array([[1.0, 2.0], [3.0, 4.0]])
        result = _get_weights(dist, 'distance')
        expected = np.array([[1.0, 0.5], [0.33333333, 0.25]])
        np.testing.assert_array_almost_equal(result, expected)

    def test_get_weights_callable(self):
        from sklearn.neighbors.base import _get_weights
        dist = np.array([[1.0, 2.0], [3.0, 4.0]])
        result = _get_weights(dist, lambda x: x * 2)
        expected = np.array([[2.0, 4.0], [6.0, 8.0]])
        np.testing.assert_array_almost_equal(result, expected)

    def test_get_weights_invalid(self):
        from sklearn.neighbors.base import _get_weights
        dist = np.array([[1.0, 2.0], [3.0, 4.0]])
        with pytest.raises(ValueError):
            _get_weights(dist, 'invalid')

    def test_get_weights_distance_zero_division(self):
        from sklearn.neighbors.base import _get_weights
        dist = np.array([[0.0, 2.0], [3.0, 4.0]])
        result = _get_weights(dist, 'distance')
        # Zero distances should become 1.0 (infinite weight)
        assert result[0, 0] == 1.0


