"""
Tests for django.db.migrations.autodetector.MigrationAutodetector
"""
import functools
from unittest import mock

from django.conf import settings
from django.db import models
from django.db.migrations import operations
from django.db.migrations.autodetector import MigrationAutodetector
from django.db.migrations.questioner import MigrationQuestioner
from django.db.migrations.state import ProjectState, StateApps
from django.test import SimpleTestCase, TestCase


class MigrationAutodetectorInitTest(SimpleTestCase):
    """Tests for MigrationAutodetector.__init__"""

    def test_init_with_no_questioner(self):
        from_state = ProjectState()
        to_state = ProjectState()
        detector = MigrationAutodetector(from_state, to_state)
        self.assertIsInstance(detector.questioner, MigrationQuestioner)
        self.assertEqual(detector.from_state, from_state)
        self.assertEqual(detector.to_state, to_state)

    def test_init_with_custom_questioner(self):
        from_state = ProjectState()
        to_state = ProjectState()
        custom_questioner = MigrationQuestioner()
        detector = MigrationAutodetector(from_state, to_state, questioner=custom_questioner)
        self.assertEqual(detector.questioner, custom_questioner)

    def test_existing_apps_from_from_state(self):
        # Create a state with some models
        state = ProjectState()
        state.add_model(
            ('testapp', 'MyModel'),
            models.Model('MyModel', [
                ('id', models.AutoField(primary_key=True)),
            ])
        )
        detector = MigrationAutodetector(state, ProjectState())
        self.assertIn(('testapp', 'MyModel'), detector.existing_apps)


class DeepDeconstructTest(SimpleTestCase):
    """Tests for MigrationAutodetector.deep_deconstruct"""

    def setUp(self):
        self.detector = MigrationAutodetector(ProjectState(), ProjectState())

    def test_deep_deconstruct_list(self):
        result = self.detector.deep_deconstruct([1, 2, 3])
        self.assertEqual(result, [1, 2, 3])

    def test_deep_deconstruct_tuple(self):
        result = self.detector.deep_deconstruct((1, 2, 3))
        self.assertEqual(result, (1, 2, 3))

    def test_deep_deconstruct_dict(self):
        result = self.detector.deep_deconstruct({'a': 1, 'b': 2})
        self.assertEqual(result, {'a': 1, 'b': 2})

    def test_deep_deconstruct_nested_structure(self):
        nested = {'list': [1, 2], 'tuple': (3, 4)}
        result = self.detector.deep_deconstruct(nested)
        self.assertEqual(result, {'list': [1, 2], 'tuple': (3, 4)})

    def test_deep_deconstruct_partial(self):
        def dummy_func(a, b):
            return a + b
        partial = functools.partial(dummy_func, 1)
        result = self.detector.deep_deconstruct(partial)
        self.assertEqual(result[0], dummy_func)

    def test_deep_deconstruct_type(self):
        class DummyClass:
            pass
        result = self.detector.deep_deconstruct(DummyClass)
        self.assertIs(result, DummyClass)

    def test_deep_deconstruct_field(self):
        field = models.CharField(max_length=100)
        result = self.detector.deep_deconstruct(field)
        self.assertIsInstance(result, tuple)
        self.assertEqual(len(result), 3)


