class ResolveDependencyTest(SimpleTestCase):
    """Tests for MigrationAutodetector._resolve_dependency"""

    def test_resolve_dependency_normal(self):
        dep = ('app_label', 'model_name', 'field_name', True)
        result, is_swappable = MigrationAutodetector._resolve_dependency(dep)
        self.assertEqual(result, dep)
        self.assertFalse(is_swappable)

    def test_resolve_dependency_swappable(self):
        with mock.patch.object(settings, 'AUTH_USER_MODEL', 'auth.User'):
            dep = ('__setting__', 'AUTH_USER_MODEL', 'extra')
            result, is_swappable = MigrationAutodetector._resolve_dependency(dep)
            self.assertTrue(is_swappable)
            self.assertEqual(result[0], 'auth')
            self.assertEqual(result[1], 'user')


class CheckDependencyTest(SimpleTestCase):
    """Tests for MigrationAutodetector.check_dependency"""

    def setUp(self):
        self.detector = MigrationAutodetector(ProjectState(), ProjectState())

    def test_check_dependency_created_model(self):
        operation = operations.CreateModel(
            name='TestModel',
            fields=[('id', models.AutoField(primary_key=True))]
        )
        dependency = ('app', 'TestModel', None, True)
        result = self.detector.check_dependency(operation, dependency)
        self.assertTrue(result)

    def test_check_dependency_removed_model(self):
        operation = operations.DeleteModel(name='TestModel')
        dependency = ('app', 'TestModel', None, False)
        result = self.detector.check_dependency(operation, dependency)
        self.assertTrue(result)

    def test_check_dependency_unknown_raises_valueerror(self):
        operation = operations.CreateModel(
            name='TestModel',
            fields=[('id', models.AutoField(primary_key=True))]
        )
        dependency = ('app', 'TestModel', 'unknown', 'invalid')
        with self.assertRaises(ValueError) as context:
            self.detector.check_dependency(operation, dependency)
        self.assertIn("Can't handle dependency", str(context.exception))


