class ArrangeForGraphTest(SimpleTestCase):
    """Tests for MigrationAutodetector.arrange_for_graph"""

    def setUp(self):
        self.from_state = ProjectState()
        self.to_state = ProjectState()
        self.questioner = mock.MagicMock(spec=MigrationQuestioner)
        self.questioner.ask_initial.return_value = True
        self.detector = MigrationAutodetector(self.from_state, self.to_state, questioner=self.questioner)

    def test_arrange_for_graph_with_empty_changes(self):
        graph = mock.MagicMock()
        graph.leaf_nodes.return_value = []
        changes = {}
        result = self.detector.arrange_for_graph(changes, graph)
        self.assertEqual(result, {})

    def test_arrange_for_graph_with_migrations(self):
        graph = mock.MagicMock()
        graph.leaf_nodes.return_value = [('app', '0001_initial')]

        migration = mock.MagicMock()
        migration.name = 'auto_1'
        migration.suggest_name.return_value = 'some_name'
        migration.dependencies = []

        changes = {'app': [migration]}
        result = self.detector.arrange_for_graph(changes, graph)

        self.assertIn('app', result)
        self.assertEqual(len(result['app']), 1)
        self.assertTrue(result['app'][0].name.startswith('0002'))


