def test_pytest_addoption():
    """Test pytest_addoption function registers command line options."""
    from _pytest.main import pytest_addoption

    class MockParser:
        def __init__(self):
            self.addini_calls = []
            self.groups = {}

        def addini(self, name, help, type, default):
            self.addini_calls.append((name, help, type, default))

        def getgroup(self, name, help):
            if name not in self.groups:
                self.groups[name] = MockGroup()
            return self.groups[name]

    class MockGroup:
        def __init__(self):
            self.options = []

        def _addoption(self, *args, **kwargs):
            self.options.append((args, kwargs))

        def addoption(self, *args, **kwargs):
            self.options.append((args, kwargs))

    parser = MockParser()
    pytest_addoption(parser)

    # Check that addini was called for norecursedirs and testpaths
    ini_names = [call[0] for call in parser.addini_calls]
    assert "norecursedirs" in ini_names
    assert "testpaths" in ini_names


