class QuoteUnquoteTests(SimpleTestCase):
    """Test quote and unquote functions."""

    def test_quote_simple_string(self):
        from django.contrib.admin.utils import quote
        result = quote("simple")
        self.assertEqual(result, "simple")

    def test_quote_with_slash(self):
        from django.contrib.admin.utils import quote
        result = quote("a/b")
        self.assertNotEqual(result, "a/b")
        self.assertIn("_", result)

    def test_quote_with_colon(self):
        from django.contrib.admin.utils import quote
        result = quote("a:b")
        self.assertNotEqual(result, "a:b")
        self.assertIn("_", result)

    def test_unquote_matches_quote(self):
        from django.contrib.admin.utils import quote, unquote
        original = "test/value:with:special"
        quoted = quote(original)
        unquoted = unquote(quoted)
        self.assertEqual(original, unquoted)

    def test_unquote_complex(self):
        from django.contrib.admin.utils import quote, unquote
        original = 'test/:_#?;@&=+$,"[]<>%\n\\'
        quoted = quote(original)
        unquoted = unquote(quoted)
        self.assertEqual(original, unquoted)


