class LookupNeedsDistinctTests(SimpleTestCase):
    """Test lookup_needs_distinct function."""

    def test_lookup_needs_distinct_no_relation(self):
        from django.contrib.admin.utils import lookup_needs_distinct

        class MockOpts:
            pk = type('obj', (object,), {'name': 'id'})()

            def get_field(self, name):
                raise FieldDoesNotExist()

        opts = MockOpts()
        result = lookup_needs_distinct(opts, 'field')
        self.assertFalse(result)

    def test_lookup_needs_distinct_with_m2m(self):
        from django.contrib.admin.utils import lookup_needs_distinct

        class MockPathInfo:
            m2m = True
            to_opts = type('obj', (object,), {})()

        class MockField:
            def get_path_info(self):
                return [MockPathInfo()]

        class MockOpts:
            pk = type('obj', (object,), {'name': 'id'})()

            def get_field(self, name):
                if name == 'related':
                    return MockField()
                raise FieldDoesNotExist()

        opts = MockOpts()
        result = lookup_needs_distinct(opts, 'related')
        self.assertTrue(result)


