class TestForeignKeyGetDefaultObjectDefault(SimpleTestCase):
    """Tests for ForeignKey.get_default when default is an object."""

    def test_get_default_object_default(self):
        from django.db.models.fields.related import ForeignKey
        from django.db.models.deletion import CASCADE

        class MockModel:
            _meta = type('Meta', (), {
                'pk': type('PK', (), {'name': 'id'})(),
                'model_name': 'testmodel',
                'app_label': 'test_app',
                'object_name': 'TestModel'
            })()

        class MockRemoteField:
            on_delete = CASCADE
            model = MockModel

        class MockDefaultObject:
            id = 123

        field = ForeignKey(MockModel, CASCADE)
        field.remote_field = MockRemoteField()

        # Override get_default to return a default object
        original_get_default = field.__class__.get_default
        field.__class__.get_default = lambda self: MockDefaultObject()

        try:
            result = field.get_default()
            self.assertEqual(result, 123)
        finally:
            field.__class__.get_default = original_get_default

