                assert False
        """)
        result = testdir.runpytest("--runxfail")
        result.assert_outcomes(failed=1)

    def test_xfail_strict_ini(self, testdir):
        """Test xfail_strict ini option."""
        testdir.makeini("""
            [pytest]
            xfail_strict = true
        """)
        testdir.makepyfile("""
            import pytest

            @pytest.mark.xfail(reason="strict by default")
            def test_xpass_strict_default():
                assert True
        """)
        result = testdir.runpytest()
        result.assert_outcomes(failed=1)

