        d = Derivative(x**2, x)
        assert d.canonical == d

    def test_derivative_sort_variable_count(self):
        vsort = Derivative._sort_variable_count
        result = vsort([(x, 1), (x, 1)])
        assert len(result) == 1
        assert result[0][1] == 2

    def test_derivative_doit_numerically(self):
        d = Derivative(sin(x), x)
        try:
